-- ── story 2-10b: licence plates (LPNs) at receiving ──────────────────────
-- Generated by drizzle-kit (the table and its indexes) and hand-amended
-- around the generated part: the fail-fast guard, `IF NOT EXISTS` on the
-- table and every index (guide §3, linted from 0089 on), the CHECKs, RLS and
-- the post-migration probe (drizzle-kit is blind to CHECKs and policies;
-- `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive: one new, empty table. No existing row or constraint is touched,
-- so the migration takes no lock on a populated table, and the CHECKs are
-- plain (nothing to validate). No foreign keys (IMPLEMENTATION-GUIDE §3).
--
-- The vocabularies are pinned against their TS tuples by test/lpns.spec.ts:
-- `LPN_STATUSES` (`active | placed | voided`) and `LPN_VOID_REASON_CODES`
-- (`misprint | wrong-quantity | label-damaged | other`).

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'lpns'
	) THEN
		RAISE EXCEPTION 'migration 0109: lpns already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "lpns" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"warehouse_id" uuid NOT NULL,
	"grn_id" uuid NOT NULL,
	"grn_line_id" uuid NOT NULL,
	"sku_id" uuid NOT NULL,
	"batch_id" uuid,
	"client_id" uuid NOT NULL,
	"seq" bigint NOT NULL,
	"code" text NOT NULL,
	"qty" bigint NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"created_by" uuid NOT NULL,
	"placed_at" timestamp with time zone,
	"placement_id" uuid,
	"voided_at" timestamp with time zone,
	"voided_by" uuid,
	"void_reason_code" text,
	"void_note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "lpns_tenant_seq_unique" ON "lpns" USING btree ("tenant_id","seq");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "lpns_tenant_code_unique" ON "lpns" USING btree ("tenant_id","code");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "lpns_tenant_grn_seq_idx" ON "lpns" USING btree ("tenant_id","grn_id","seq");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "lpns_tenant_grn_line_idx" ON "lpns" USING btree ("tenant_id","grn_line_id");--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only) ──────────────────────────
-- Postgres evaluates a row's CHECKs in NAME order; each refused probe below
-- violates only its target. Every nullable vocabulary says IS NOT NULL
-- before IN (guide §3).
ALTER TABLE "lpns" ADD CONSTRAINT "lpns_qty_positive" CHECK ("qty" > 0);--> statement-breakpoint
ALTER TABLE "lpns" ADD CONSTRAINT "lpns_seq_positive" CHECK ("seq" > 0);--> statement-breakpoint
-- Decision 4 — `LPN-` and at least six digits (zero-padded to 6, longer past 999,999).
ALTER TABLE "lpns" ADD CONSTRAINT "lpns_code_format" CHECK ("code" ~ '^LPN-[0-9]{6,}$');--> statement-breakpoint
ALTER TABLE "lpns" ADD CONSTRAINT "lpns_status_check" CHECK (
	"status" IN ('active', 'placed', 'voided')
);--> statement-breakpoint
-- A1 — placed ⇔ the placement instant and the placement id are both set.
ALTER TABLE "lpns" ADD CONSTRAINT "lpns_placed_pairing" CHECK (
	("status" = 'placed') = ("placed_at" IS NOT NULL AND "placement_id" IS NOT NULL)
	AND ("placed_at" IS NULL) = ("placement_id" IS NULL)
);--> statement-breakpoint
-- Decision 7, A10 — voided ⇔ the instant, the voider and the reason are all
-- set; a note only ever rides a reason.
ALTER TABLE "lpns" ADD CONSTRAINT "lpns_voided_pairing" CHECK (
	("status" = 'voided') = ("voided_at" IS NOT NULL AND "voided_by" IS NOT NULL AND "void_reason_code" IS NOT NULL)
	AND ("voided_at" IS NULL) = ("voided_by" IS NULL)
	AND ("voided_by" IS NULL) = ("void_reason_code" IS NULL)
	AND ("void_note" IS NULL OR "void_reason_code" IS NOT NULL)
);--> statement-breakpoint
-- A10 — the void reason vocabulary.
ALTER TABLE "lpns" ADD CONSTRAINT "lpns_void_reason_check" CHECK (
	"void_reason_code" IS NULL
	OR ("void_reason_code" IS NOT NULL AND "void_reason_code" IN ('misprint', 'wrong-quantity', 'label-damaged', 'other'))
);--> statement-breakpoint
-- A10 — the note: 1–200 characters, and required with `other`.
ALTER TABLE "lpns" ADD CONSTRAINT "lpns_void_note_check" CHECK (
	("void_note" IS NULL OR char_length("void_note") BETWEEN 1 AND 200)
	AND ("void_reason_code" IS DISTINCT FROM 'other' OR "void_note" IS NOT NULL)
);--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy (the 0014 shape) ────────
ALTER TABLE "lpns" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "lpns_tenant_isolation" ON "lpns"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0105 model) ────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction — a valid
-- base row, then the one change under test — and must be refused BY ITS
-- NAMED CONSTRAINT (guide §3, CHECKs in name order).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	g uuid := gen_random_uuid();
	l uuid := gen_random_uuid();
	s uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	r uuid;
	n bigint := 0;
	refused_by text;
	expected text;
	probe text;
	base text;
BEGIN
	IF NOT (SELECT relrowsecurity FROM pg_class WHERE relname = 'lpns') THEN
		RAISE EXCEPTION 'migration 0109: row level security is not enabled on lpns.';
	END IF;
	-- (1) accepted shapes: an active LPN (batched and not), a placed one, a
	-- voided one without a note, a voided `other` with a 200-character note,
	-- and a seven-digit code (past 999,999).
	BEGIN
		INSERT INTO "lpns" ("id","tenant_id","warehouse_id","grn_id","grn_line_id","sku_id","batch_id","client_id","seq","code","qty","created_by")
		VALUES (gen_random_uuid(), t, w, g, l, s, NULL, c, 1, 'LPN-000001', 40000, u),
		       (gen_random_uuid(), t, w, g, l, s, gen_random_uuid(), c, 2, 'LPN-000002', 1, u);
		INSERT INTO "lpns" ("id","tenant_id","warehouse_id","grn_id","grn_line_id","sku_id","client_id","seq","code","qty","created_by","status","placed_at","placement_id")
		VALUES (gen_random_uuid(), t, w, g, l, s, c, 3, 'LPN-000003', 20000, u, 'placed', now(), gen_random_uuid());
		INSERT INTO "lpns" ("id","tenant_id","warehouse_id","grn_id","grn_line_id","sku_id","client_id","seq","code","qty","created_by","status","voided_at","voided_by","void_reason_code")
		VALUES (gen_random_uuid(), t, w, g, l, s, c, 4, 'LPN-000004', 20000, u, 'voided', now(), u, 'misprint'),
		       (gen_random_uuid(), t, w, g, l, s, c, 5, 'LPN-000005', 20000, u, 'voided', now(), u, 'wrong-quantity'),
		       (gen_random_uuid(), t, w, g, l, s, c, 6, 'LPN-000006', 20000, u, 'voided', now(), u, 'label-damaged');
		INSERT INTO "lpns" ("id","tenant_id","warehouse_id","grn_id","grn_line_id","sku_id","client_id","seq","code","qty","created_by","status","voided_at","voided_by","void_reason_code","void_note")
		VALUES (gen_random_uuid(), t, w, g, l, s, c, 7, 'LPN-000007', 20000, u, 'voided', now(), u, 'other', repeat('x', 200));
		INSERT INTO "lpns" ("id","tenant_id","warehouse_id","grn_id","grn_line_id","sku_id","client_id","seq","code","qty","created_by")
		VALUES (gen_random_uuid(), t, w, g, l, s, c, 1000000, 'LPN-1000000', 500, u);
		RAISE EXCEPTION USING ERRCODE = 'P0109', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0109: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0109' THEN
			NULL;
	END;
	-- (2) refused shapes: a base row of the named status, then one change.
	FOREACH probe IN ARRAY ARRAY[
		'zero qty', 'zero seq', 'short code', 'lowercase code', 'unknown status',
		'placed without a placement', 'active with a placement', 'placement id without an instant',
		'voided without a reason', 'active with a void', 'note without a reason',
		'unknown void reason', 'other without a note', 'overlong note', 'empty note',
		'duplicate seq', 'duplicate code'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'zero qty' THEN 'lpns_qty_positive'
			WHEN 'zero seq' THEN 'lpns_seq_positive'
			WHEN 'short code' THEN 'lpns_code_format'
			WHEN 'lowercase code' THEN 'lpns_code_format'
			WHEN 'unknown status' THEN 'lpns_status_check'
			WHEN 'placed without a placement' THEN 'lpns_placed_pairing'
			WHEN 'active with a placement' THEN 'lpns_placed_pairing'
			WHEN 'placement id without an instant' THEN 'lpns_placed_pairing'
			WHEN 'voided without a reason' THEN 'lpns_voided_pairing'
			WHEN 'active with a void' THEN 'lpns_voided_pairing'
			WHEN 'note without a reason' THEN 'lpns_voided_pairing'
			WHEN 'unknown void reason' THEN 'lpns_void_reason_check'
			WHEN 'other without a note' THEN 'lpns_void_note_check'
			WHEN 'overlong note' THEN 'lpns_void_note_check'
			WHEN 'empty note' THEN 'lpns_void_note_check'
			WHEN 'duplicate seq' THEN 'lpns_tenant_seq_unique'
			ELSE 'lpns_tenant_code_unique'
		END;
		base := CASE
			WHEN probe IN ('unknown void reason', 'other without a note', 'overlong note', 'empty note') THEN 'voided'
			ELSE 'active'
		END;
		BEGIN
			r := gen_random_uuid();
			n := n + 1;
			INSERT INTO "lpns" ("id","tenant_id","warehouse_id","grn_id","grn_line_id","sku_id","client_id","seq","code","qty","created_by")
			VALUES (r, t, w, g, l, s, c, 100 + n, 'LPN-' || lpad((100 + n)::text, 6, '0'), 1000, u);
			IF base = 'voided' THEN
				UPDATE "lpns" SET "status" = 'voided', "voided_at" = now(), "voided_by" = u, "void_reason_code" = 'misprint' WHERE "id" = r;
			END IF;
			CASE probe
				WHEN 'zero qty' THEN UPDATE "lpns" SET "qty" = 0 WHERE "id" = r;
				WHEN 'zero seq' THEN UPDATE "lpns" SET "seq" = 0 WHERE "id" = r;
				WHEN 'short code' THEN UPDATE "lpns" SET "code" = 'LPN-42' WHERE "id" = r;
				WHEN 'lowercase code' THEN UPDATE "lpns" SET "code" = 'lpn-000042' WHERE "id" = r;
				WHEN 'unknown status' THEN UPDATE "lpns" SET "status" = 'lost' WHERE "id" = r;
				WHEN 'placed without a placement' THEN UPDATE "lpns" SET "status" = 'placed', "placed_at" = now() WHERE "id" = r;
				WHEN 'active with a placement' THEN UPDATE "lpns" SET "placed_at" = now(), "placement_id" = gen_random_uuid() WHERE "id" = r;
				WHEN 'placement id without an instant' THEN UPDATE "lpns" SET "status" = 'placed', "placement_id" = gen_random_uuid() WHERE "id" = r;
				WHEN 'voided without a reason' THEN UPDATE "lpns" SET "status" = 'voided', "voided_at" = now(), "voided_by" = u WHERE "id" = r;
				WHEN 'active with a void' THEN UPDATE "lpns" SET "voided_at" = now(), "voided_by" = u, "void_reason_code" = 'misprint' WHERE "id" = r;
				WHEN 'note without a reason' THEN UPDATE "lpns" SET "void_note" = 'x' WHERE "id" = r;
				WHEN 'unknown void reason' THEN UPDATE "lpns" SET "void_reason_code" = 'smudged' WHERE "id" = r;
				WHEN 'other without a note' THEN UPDATE "lpns" SET "void_reason_code" = 'other' WHERE "id" = r;
				WHEN 'overlong note' THEN UPDATE "lpns" SET "void_note" = repeat('x', 201) WHERE "id" = r;
				WHEN 'empty note' THEN UPDATE "lpns" SET "void_note" = '' WHERE "id" = r;
				WHEN 'duplicate seq' THEN
					INSERT INTO "lpns" ("id","tenant_id","warehouse_id","grn_id","grn_line_id","sku_id","client_id","seq","code","qty","created_by")
					VALUES (gen_random_uuid(), t, w, g, l, s, c, 100 + n, 'LPN-900000', 1000, u);
				WHEN 'duplicate code' THEN
					INSERT INTO "lpns" ("id","tenant_id","warehouse_id","grn_id","grn_line_id","sku_id","client_id","seq","code","qty","created_by")
					VALUES (gen_random_uuid(), t, w, g, l, s, c, 900001, 'LPN-' || lpad((100 + n)::text, 6, '0'), 1000, u);
			END CASE;
			RAISE EXCEPTION USING ERRCODE = 'P0109', MESSAGE = 'probe accepted';
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0109' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0109: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "lpns" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0109: a probe row survived.';
	END IF;
END $$;
